`timescale 1ns/10ps
`define PERIOD    6.0
`define MAX_CYCLE 10000000
`define RST_DELAY 2.0
`define SDFFILE   "../02_SYN/Netlist/MM_syn.sdf"

// Point these to the files generated by the Python script
`define IDATA_A "../00_TESTBED/inputA_int8.txt"
`define IDATA_B "../00_TESTBED/inputB_int8.txt"
`define ODATA   "../00_TESTBED/golden_int8.txt"

module testbench #(
    // =========================================================
    // PARAMETERS (Must match Python config)
    // =========================================================
    parameter M = 512,
    parameter N = 512,
    parameter K = 256,
    parameter AD = 16,
    parameter VL = 32,  // Change here for sweeping (8, 16, 32)
    parameter VS = 32,  // Change here for sweeping (16, 32, 64)
    
    parameter SUM_W = 24,
    parameter ACC_W = SUM_W * VL,
    // Input A width: VL lines * VS items * 8 bits
    parameter DATA_A_WIDTH = VL * VS * 8, 
    // Input B width: VS items * 8 bits
    parameter DATA_B_WIDTH = VS * 8,
    // Output Width: VL lines * 24 bits
    parameter DATA_OUT_WIDTH = VL * 24 
)();

    // Derived loop limits
    localparam CNT_M_MAX = M/VL;
    localparam CNT_N_MAX = N/AD;
    localparam CNT_K_MAX = K/VS;

    wire                                clk, rst_n;
    reg                                 output_end;
    reg                                 in_valid;
    
    // Dynamic width input ports
    reg         [DATA_A_WIDTH-1:0]      in_a;
    reg         [DATA_B_WIDTH-1:0]      in_b;
    
    // Removed o_addr_a / o_addr_b as TB is now Master
    wire                                out_valid;
    wire signed [ACC_W-1:0]             out_acc;

    integer i, j, latency;
    integer correct, error;

    // Memory Arrays
    // A: Stores (M/VL)*(K/VS) blocks.
    reg  [DATA_A_WIDTH-1:0]   input_data_a[0:(M/VL)*(K/VS)-1];
    // B: Stores (N/AD)*(K/VS)*AD blocks.
    reg  [DATA_B_WIDTH-1:0]   input_data_b[0:(N/AD)*(K/VS)*AD-1];
    
    // Output check arrays
    reg  [ACC_W-1:0]          output_data [0:M*N/VL-1]; // Note: M*N/VL lines in golden? 
                                                        // Actually golden writes M/VL * N/AD * AD lines.
                                                        // M/VL * N = M*N/VL. Correct.
    reg  [ACC_W-1:0]          golden_data [0:M*N/VL-1];

    // Load Files
    initial begin
        $readmemb(`IDATA_A, input_data_a);
        $readmemb(`IDATA_B, input_data_b);
        $readmemb(`ODATA, golden_data);
    end

    clk_gen u_clk_gen (
        .clk   (clk  ),
        .rst   (     ),
        .rst_n (rst_n)
    );

    // DUT Instantiation
    // Note: You must modify your MM module interface to accept stream inputs
    // without requesting addresses, OR leave o_addr unconnected if modified internally.
    MM #(
        .M(M), .N(N), .K(K), .AD(AD), .VL(VL), .VS(VS) 
    ) u_mm (
        .i_clk(clk),
        .i_rst_n(rst_n),
        .i_in_valid(in_valid),
        .i_vec_a(in_a),
        .i_vec_b(in_b),
        // .o_addr_a(), // Disconnected, handled by TB
        // .o_addr_b(), // Disconnected, handled by TB
        .o_out_valid(out_valid),
        .o_acc(out_acc)
    );

    `ifdef SDF
        initial $sdf_annotate(`SDFFILE, u_mm);
    `endif

    initial begin
        $fsdbDumpfile("MM.fsdb");
        $fsdbDumpvars(0, testbench, "+mda");
    end

    // =========================================================
    // Input Feeding Logic (Loop Counters)
    // =========================================================
    // Hierarchy from Diagram:
    // Outer -> Inner: m -> n -> k -> a (stationary)
    integer cnt_m, cnt_n, cnt_k, cnt_a;
    
    // Indices for memory arrays
    integer idx_a, idx_b;

    always @(negedge clk or negedge rst_n) begin
        if (!rst_n) begin
            in_valid <= 0;
            in_a     <= 0;
            in_b     <= 0;
            cnt_m    <= 0;
            cnt_n    <= 0;
            cnt_k    <= 0;
            cnt_a    <= 0;
            latency  <= 0;
        end else begin
            // Simple Valid generation: Always valid until done
            // Check termination condition
            if (cnt_m < CNT_M_MAX) begin
                in_valid <= 1'b1;
                latency  <= latency + 1;

                // ----------------------------------------
                // Calculate Indices based on Loop State
                // ----------------------------------------
                
                // Index A: Depends on m and k. 
                // A is stationary for 'cnt_a' loop (AD cycles).
                idx_a = (cnt_m * CNT_K_MAX) + cnt_k;
                
                // Index B: Depends on n, a, k.
                // Based on generator logic: (n * AD + a) * (K/VS) + k
                idx_b = ((cnt_n * AD) + cnt_a) * CNT_K_MAX + cnt_k;

                // Drive Inputs
                in_a <= input_data_a[idx_a];
                in_b <= input_data_b[idx_b];

                // ----------------------------------------
                // Increment Counters (Inner to Outer)
                // ----------------------------------------
                // - Matches diagram loop order
                // Inner loop: V (VS) and L (VL) are handled spatially (in parallel)
                // Next loop: a (0 to AD-1) -> A Input Stationary
                if (cnt_a < AD - 1) begin
                    cnt_a <= cnt_a + 1;
                end else begin
                    cnt_a <= 0;
                    // Next loop: k (0 to K/VS - 1) -> Output Stationary
                    if (cnt_k < CNT_K_MAX - 1) begin
                        cnt_k <= cnt_k + 1;
                    end else begin
                        cnt_k <= 0;
                        // Next loop: n (0 to N/AD - 1)
                        if (cnt_n < CNT_N_MAX - 1) begin
                            cnt_n <= cnt_n + 1;
                        end else begin
                            cnt_n <= 0;
                            // Outer loop: m (0 to M/VL - 1)
                            cnt_m <= cnt_m + 1;
                        end
                    end
                end
            end else begin
                in_valid <= 1'b0;
                in_a <= 'd0;
                in_b <= 'd0;
            end
        end
    end

    // =========================================================
    // Output Checking Logic
    // =========================================================
    initial begin
        output_end = 0;
        j = 0;
        wait (rst_n === 1'b1);
        
        // Wait loop for outputs
        while (j < (M/VL) * N) begin // Total output lines: (M/VL) * N blocks? 
                                     // No, Golden file has (M/VL)*(N/AD) blocks. 
                                     // Each block has AD lines. Total lines = (M/VL)*(N/AD)*AD = M*N/VL.
            @(negedge clk);
            if (out_valid) begin
                output_data[j] = out_acc;
                
                // On-the-fly check (optional, helps debug)
                if (output_data[j] !== golden_data[j])
                    $display("Error at index %d: Expected %h, Got %h", j, golden_data[j], out_acc);
                
                j = j + 1;
            end
        end
        
        @(negedge clk);
        output_end = 1;
    end

    // Final Validation
    initial begin
        wait (output_end);
        $display("Latency: %0d", latency);
        
        error = 0;
        for (i = 0; i < M*N/VL; i = i + 1) begin
            if (golden_data[i] !== output_data[i]) begin
                error = error + 1;
            end
        end

        if(error == 0) 
            $display(">>> Congratulations! Simulation Passed with VL=%0d, VS=%0d", VL, VS);
        else 
            $display(">>> Failed with %0d errors.", error);
            
        $finish;
    end

endmodule

module clk_gen (output reg clk, output reg rst, output reg rst_n);
    always #(`PERIOD / 2.0) clk = ~clk;
    initial begin
        clk = 0; rst = 0; rst_n = 1;
        #(`PERIOD/2); rst = 1; rst_n = 0;
        #(`RST_DELAY * `PERIOD); rst = 0; rst_n = 1;
        #(`MAX_CYCLE * `PERIOD);
        $display("Timeout"); $finish;
    end
endmodule